+import { Pool } from "pg";
+import fs from "fs";
+import path from "path";
+import { fileURLToPath } from "url";
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+
+async function introspectSchema() {
+  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+  try {
+    const result = await pool.query(`
+      SELECT
+        t.table_name,
+        json_agg(
+          json_build_object(
+            'name', c.column_name,
+            'type', c.data_type,
+            'nullable', c.is_nullable = 'YES',
+            'ordinal', c.ordinal_position
+          ) ORDER BY c.ordinal_position
+        ) as columns
+      FROM
+        information_schema.tables t
+      JOIN
+        information_schema.columns c ON t.table_name = c.table_name AND t.table_schema = c.table_schema
+      WHERE
+        t.table_schema = 'public'
+      GROUP BY
+        t.table_name
+      ORDER BY
+        t.table_name
+    `);
+
+    const tables = result.rows;
+    const typeMapping = {
+      "bigint": "number",
+      "integer": "number",
+      "smallint": "number",
+      "numeric": "number",
+      "decimal": "number",
+      "real": "number",
+      "double precision": "number",
+      "boolean": "boolean",
+      "text": "string",
+      "varchar": "string",
+      "char": "string",
+      "timestamp without time zone": "Date",
+      "timestamp with time zone": "Date",
+      "date": "Date",
+      "time without time zone": "string",
+      "time with time zone": "string",
+      "uuid": "string",
+      "json": "any",
+      "jsonb": "any",
+    };
+
+    let schemaContent = `import type { ColumnType } from "kysely";\n\n`;
+
+    // Generate interface for each table
+    tables.forEach((table) => {
+      const interfaceName = capitalizeFirstLetter(table.table_name);
+      const columns = table.columns.sort((a, b) => a.ordinal - b.ordinal);
+
+      schemaContent += `export interface ${interfaceName} {\n`;
+
+      columns.forEach((col) => {
+        const tsType =
+          typeMapping[col.type] ||
+          (col.type.includes("[]") ? "any[]" : "unknown");
+        const nullable = col.nullable ? " | null" : "";
+        const generated =
+          col.type === "timestamp without time zone" &&
+          col.name === "created_at"
+            ? " & ColumnType<never, never, never>"
+            : "";
+        schemaContent += `  ${col.name}: ${tsType}${nullable}${generated};\n`;
+      });
+
+      schemaContent += `}\n\n`;
+    });
+
+    // Generate Database interface
+    schemaContent += `export interface Database {\n`;
+    tables.forEach((table) => {
+      const interfaceName = capitalizeFirstLetter(table.table_name);
+      schemaContent += `  ${table.table_name}: ${interfaceName};\n`;
+    });
+    schemaContent += `}\n`;
+
+    const schemaPath = path.join(__dirname, "../src/db/schema.ts");
+    fs.writeFileSync(schemaPath, schemaContent);
+    console.log(`✓ Schema generated: ${schemaPath}`);
+  } catch (error) {
+    console.error("Failed to introspect schema:", error.message);
+    process.exit(1);
+  } finally {
+    await pool.end();
+  }
+}
+
+function capitalizeFirstLetter(str) {
+  return str.charAt(0).toUpperCase() + str.slice(1);
+}
+
+introspectSchema();
